import pandas as pd
import seaborn as sns
from collections import Counter
from textblob import TextBlob
from matplotlib import pyplot as plt

def task_func(text, n, top_k):
    if not isinstance(text, str):
        return None

    try:
        n = int(n)
        top_k = int(top_k)
    except (TypeError, ValueError):
        return None

    if n <= 0 or top_k <= 0 or not text.strip():
        return None

    try:
        ngrams = TextBlob(text).ngrams(n)
        ngram_strings = [" ".join(map(str, ngram)) for ngram in ngrams]
    except Exception:
        words = text.split()
        ngram_strings = [
            " ".join(words[i:i + n])
            for i in range(len(words) - n + 1)
        ] if len(words) >= n else []

    if not ngram_strings:
        return None

    counts = Counter(ngram_strings).most_common(top_k)
    df = pd.DataFrame(counts, columns=["ngram", "count"])

    plt.figure(figsize=(10, max(4, 0.45 * len(df))))
    sns.barplot(data=df, x="count", y="ngram", hue="ngram", palette="viridis", legend=False)
    plt.xlabel("Frequency")
    plt.ylabel(f"{n}-gram")
    plt.title(f"Top {len(df)} {n}-grams")
    plt.tight_layout()
    plt.show()

    return None
